{
  "status": "AUTHORIZED_UNIQUE",
  "coverage": [
    {
      "text": "请",
      "role": "CONTEXT",
      "explanation": "礼貌请求标记，不增加动作，仅表明后续内容是用户的执行指令。"
    },
    {
      "text": "先",
      "role": "RELATION",
      "explanation": "指定向前行走是整个计划中的第一步。"
    },
    {
      "text": "向前走4米",
      "role": "ACTION",
      "explanation": "请求向前行走4米，编译为 walk_forward，distance_m 为 4.0。"
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "分隔相邻动作子句，不改变动作内容或执行顺序。"
    },
    {
      "text": "接着",
      "role": "RELATION",
      "explanation": "指定左转在向前走之后执行，形成第二个动作。"
    },
    {
      "text": "左转45度",
      "role": "ACTION",
      "explanation": "请求左转45度；左转为正角度，编译为 turn，angle_deg 为 45.0。"
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "分隔相邻动作子句，不改变动作内容或执行顺序。"
    },
    {
      "text": "最后",
      "role": "RELATION",
      "explanation": "指定停止是执行顺序中的最后一步。"
    },
    {
      "text": "停下来",
      "role": "ACTION",
      "explanation": "请求停止，编译为空参数的 stop。"
    }
  ],
  "dimensions": {
    "action_multiplicity": {
      "status": "UNIQUE",
      "explanation": "源文只请求三个动作：向前走4米、左转45度、停下来；没有编辑、替换或重复动作。"
    },
    "action_order": {
      "status": "UNIQUE",
      "explanation": "先、接着、最后明确给出唯一线性顺序：先 walk_forward，再 turn，最后 stop。"
    },
    "correction_scope": {
      "status": "UNIQUE",
      "explanation": "源文没有修正、撤回或替换任何动作或参数，因此该维度不适用且不引入其他解释。"
    },
    "repetition_scope": {
      "status": "UNIQUE",
      "explanation": "源文没有要求重复任何动作；三个动作各自仅执行一次。"
    },
    "reference_resolution": {
      "status": "UNIQUE",
      "explanation": "向前、左转和停下来均由当前指令直接说明；没有需要外部上下文才能确定的代词或省略参数。"
    },
    "temporal_relations": {
      "status": "UNIQUE",
      "explanation": "先、接着、最后建立单一顺序关系，每个后续动作依赖前一个动作，没有等待、同时或完成条件的额外关系。"
    },
    "unresolved_relations": {
      "status": "UNIQUE",
      "explanation": "源文没有显式保留未解决的顺序、范围、选择或关系；完整关系可唯一表示。"
    }
  },
  "authorized_plan": [
    {
      "id": "s1",
      "skill": "walk_forward",
      "parameters": {
        "distance_m": 4.0
      },
      "depends_on": []
    },
    {
      "id": "s2",
      "skill": "turn",
      "parameters": {
        "angle_deg": 45.0
      },
      "depends_on": [
        "s1"
      ]
    },
    {
      "id": "s3",
      "skill": "stop",
      "parameters": {},
      "depends_on": [
        "s2"
      ]
    }
  ]
}
